print(single_student('2'), single_student('9'))

solution.code:
def single_student(students, student_id):
    for s in students:
        if s['_id'] == student_id:
            return {'status': 200, 'student': s}
    return {'status': 404}

def delete_student(students, student_id):
    for s in students:
        if s['_id'] == student_id:
            students.remove(s)
            return {'status': 200}
    return {'status': 404}

